 package org.jboss.as.ejb3.subsystem;

 import org.jboss.as.controller.AbstractWriteAttributeHandler;
 import org.jboss.as.controller.AttributeDefinition;
 import org.jboss.as.controller.OperationContext;
 import org.jboss.as.controller.OperationFailedException;
 import org.jboss.as.controller.PathAddress;
 import org.jboss.as.ejb3.deployment.processors.EJBDefaultPermissionsProcessor;
 import org.jboss.dmr.ModelNode;

 /**
  * Write handler for the default missing method permission attribute
  *
  * @author Stuart Douglas
  */
 class EJBDisableDefaultEJBPermissionsWriteHandler extends AbstractWriteAttributeHandler<Void> {

     private final AttributeDefinition attributeDefinition;
     private final EJBDefaultPermissionsProcessor ejbDefaultPermissionsProcessor;

     EJBDisableDefaultEJBPermissionsWriteHandler(final AttributeDefinition attributeDefinition, final EJBDefaultPermissionsProcessor ejbDefaultPermissionsProcessor) {
         super(attributeDefinition);
         this.attributeDefinition = attributeDefinition;
         this.ejbDefaultPermissionsProcessor = ejbDefaultPermissionsProcessor;
     }

     @Override
     protected boolean applyUpdateToRuntime(OperationContext context, ModelNode operation, String attributeName,
                                            ModelNode resolvedValue, ModelNode currentValue, HandbackHolder<Void> handbackHolder) throws OperationFailedException {
         final ModelNode model = context.readResource(PathAddress.EMPTY_ADDRESS).getModel();
         apply(context, model);

         return false;
     }

     @Override
     protected void revertUpdateToRuntime(OperationContext context, ModelNode operation, String attributeName,
                                          ModelNode valueToRestore, ModelNode valueToRevert, Void handback) throws OperationFailedException {
         final ModelNode restored = context.readResource(PathAddress.EMPTY_ADDRESS).getModel().clone();
         restored.get(attributeName).set(valueToRestore);
         apply(context, restored);
     }

     private void apply(final OperationContext context, final ModelNode model) throws OperationFailedException {

         if (this.ejbDefaultPermissionsProcessor == null) {
             return;
         }
         final ModelNode modelNode = this.attributeDefinition.resolveModelAttribute(context, model);
         final Boolean value = modelNode.asBoolean();
         boolean realValue = value == null ? false : value;
         this.ejbDefaultPermissionsProcessor.setEnabled(!realValue);
     }

 }

